[InitializeOnLoad]public static class GridShiftPerformanceChecks {
 static GridShiftPerformanceChecks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("Perf7",false)){SessionState.SetBool("Perf7",false);var go=new GameObject("Native7Checks");Object.DontDestroyOnLoad(go);go.AddComponent<GridShiftPerformancePlayChecks>();}};}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){if(SessionState.GetBool("Perf7",false)){DeliverySaveStore.OverridePath=Path.GetFullPath("performance-save.json");GridShiftControls.Prefix="GS.Native7.Keys.";GridShiftControls.Reset();GridShiftTutorial.Prefix="GS.Native7.Tutorial.";GridShiftTutorial.Reopen();GridShiftTutorial.Skip();}}
 public static void SettingsBatch(){SessionState.SetBool("PerfSettingsOnly",true);Batch();}
 public static void Batch(){if(Application.productName!="GridShift Performance Validation")throw new InvalidOperationException("Execute os testes em uma cópia com productName GridShift Performance Validation para isolar preferências e salvamentos.");EditorSceneManager.OpenScene("Assets/Scenes/SampleScene.unity");foreach(var w in Object.FindObjectsByType<ClimaReal>(FindObjectsSortMode.None))w.enabled=false;SessionState.SetBool("Perf7",true);EditorApplication.isPlaying=true;}
}public sealed class GridShiftPerformancePlayChecks:MonoBehaviour {
 [Serializable]class State{public string text,href,value;public float x,y,dpr;public bool present;}
 StringBuilder report=new StringBuilder();List<string> errors=new List<string>();List<InputDevice> disabled=new List<InputDevice>();Keyboard keyboard;Mouse mouse;GridShiftUwbTerminal host;Camera view;string expected,reply;int id;State state;
 void Check(bool ok,string label){if(!ok)throw new Exception(label);report.AppendLine("PASS "+label);File.WriteAllText("performance-progress.txt",report.ToString());}
 void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)errors.Add(text);}
 void Current(){keyboard.MakeCurrent();mouse.MakeCurrent();}
 void Loaded(Scene scene,LoadSceneMode mode){foreach(var root in scene.GetRootGameObjects())foreach(var weather in root.GetComponentsInChildren<ClimaReal>(true))weather.enabled=false;}
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=60;QualitySettings.vSyncCount=0;Time.timeScale=1;Application.logMessageReceived+=Log;SceneManager.sceneLoaded+=Loaded;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;foreach(var d in InputSystem.devices.ToArray())if(d is Mouse||d is Keyboard){InputSystem.DisableDevice(d);disabled.Add(d);}keyboard=InputSystem.AddDevice<Keyboard>();mouse=InputSystem.AddDevice<Mouse>();InputSystem.onAfterUpdate+=Current;
  var routines=new Stack<IEnumerator>();routines.Push(Run());bool success=true;while(routines.Count>0){object value=null;bool more;try{more=routines.Peek().MoveNext();if(more)value=routines.Peek().Current;}catch(Exception e){success=false;report.AppendLine("FAIL "+e);break;}if(!more){routines.Pop();continue;}if(value is IEnumerator nested&&!(value is CustomYieldInstruction)){routines.Push(nested);continue;}yield return value;}
  InputSystem.onAfterUpdate-=Current;InputSystem.RemoveDevice(keyboard);InputSystem.RemoveDevice(mouse);foreach(var d in disabled)if(d.added)InputSystem.EnableDevice(d);Application.logMessageReceived-=Log;SceneManager.sceneLoaded-=Loaded;success&=errors.Count==0;report.AppendLine("Erros: "+string.Join("; ",errors));report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));File.WriteAllText("performance-results.txt",report.ToString());EditorApplication.Exit(success?0:1);
 }
 IEnumerator Until(Func<bool> test,float timeout,string label){float end=Time.realtimeSinceStartup+timeout;while(!test()&&Time.realtimeSinceStartup<end)yield return null;if(!test())throw new Exception("Timeout "+label);}
 IEnumerator Tap(Key key){InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;yield return null;}
 void Bind(GridShiftUwbTerminal adapter,Camera camera){host=adapter;view=camera;host.browser.browserClient.OnTitleChange+=title=>{if(expected!=null&&title.StartsWith(expected))reply=title;};}
 IEnumerator Query(string expression){expected="GRIDSHIFT_V7_"+(++id)+"|";reply=null;host.browser.browserClient.ExecuteJs("document.title='"+expected+"'+JSON.stringify("+expression+")");yield return Until(()=>reply!=null,8,"JS");state=JsonUtility.FromJson<State>(reply.Substring(expected.Length));}
 Vector2 Point(float x,float y){var rect=host.browser.GetComponent<RectTransform>();var b=rect.rect;var texture=host.browser.browserClient.BrowserTexture;return view.WorldToScreenPoint(rect.TransformPoint(new Vector3(b.xMin+x/texture.width*b.width,b.yMax-y/texture.height*b.height)));}
 IEnumerator Click(Vector2 point){InputSystem.QueueStateEvent(mouse,new MouseState{position=point});yield return null;yield return null;InputSystem.QueueStateEvent(mouse,new MouseState{position=point,buttons=1});yield return null;yield return null;InputSystem.QueueStateEvent(mouse,new MouseState{position=point});yield return null;yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator WebInput(){
  yield return Query("(()=>{let e=document.createElement('input');e.id='gridshift-test-input';e.style='position:fixed;left:20px;top:140px;width:300px;height:60px;z-index:2147483647';document.body.appendChild(e);let r=e.getBoundingClientRect();return {x:(r.x+r.width/2)*devicePixelRatio,y:(r.y+r.height/2)*devicePixelRatio,present:r.width>0&&r.height>0,text:(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)?.outerHTML||String())}})()");
  yield return Click(Point(state.x,state.y));foreach(char c in "GridShift ação42"){InputSystem.QueueTextEvent(keyboard,c);yield return null;}yield return new WaitForSecondsRealtime(.4f);yield return Query("({value:document.getElementById('gridshift-test-input').value})");Check(state.value=="GridShift ação42","mouse e digitação real a 200% no dispositivo ativo");yield return Tap(Key.Backspace);yield return new WaitForSecondsRealtime(.3f);yield return Query("({value:document.getElementById('gridshift-test-input').value})");Check(state.value=="GridShift ação4","Backspace no navegador ativo; valor="+state.value);host.browser.browserClient.ExecuteJs("document.getElementById('gridshift-test-input').remove()");yield return null;
 }
 [Serializable]class TokenWrap{public string value;}
 string Quote(string value){return JsonUtility.ToJson(new TokenWrap{value=value}).Substring(9).TrimEnd('}');}
 IEnumerator Sample(string label){
  yield return new WaitForSecondsRealtime(3);var frames=new List<double>();var gc=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Memory,"GC Allocated In Frame",1);var main=Unity.Profiling.ProfilerRecorder.StartNew(Unity.Profiling.ProfilerCategory.Internal,"Main Thread",1);long allocations=0,cpu=0;int n=0;double end=Time.realtimeSinceStartupAsDouble+12;
  while(Time.realtimeSinceStartupAsDouble<end){yield return null;frames.Add(Time.unscaledDeltaTime*1000);if(gc.Valid)allocations+=gc.LastValue;if(main.Valid)cpu+=main.LastValue;n++;}
  frames.Sort();report.AppendLine("MEASURE "+label+" frames="+n+" avg_ms="+frames.Average().ToString("F2")+" p95_ms="+frames[(int)(frames.Count*.95)].ToString("F2")+" cpu_ms="+(cpu/(double)Math.Max(1,n)/1000000).ToString("F2")+" gc_bytes_frame="+(allocations/Math.Max(1,n))+" memory="+UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong()+" cars="+TrafficCar.Active.Count);gc.Dispose();main.Dispose();File.WriteAllText("performance-progress.txt",report.ToString());
 }
 IEnumerator Wheel(Vector2 point,float delta){InputSystem.QueueStateEvent(mouse,new MouseState{position=point});yield return null;yield return null;InputSystem.QueueStateEvent(mouse,new MouseState{position=point,scroll=new Vector2(0,delta)});yield return null;yield return null;yield return new WaitForSecondsRealtime(.5f);}
 IEnumerator ScrollCheck(string label){
  host.browser.browserClient.ExecuteJs("document.body.innerHTML=`<style>html,body{margin:0}#panel{position:absolute;top:20px;left:20px;width:250px;height:200px;overflow:auto;background:white}#space{height:4000px;background:linear-gradient(white,gray)}</style><div id=space></div><div id=panel><div style=height:2000px>Scroll inner</div></div>`;window.scrollTo(0,0)");yield return new WaitForSecondsRealtime(1);
  yield return Query("({dpr:devicePixelRatio})");float dpr=state.dpr;yield return Wheel(Point(350*dpr,180*dpr),-1);yield return Query("({y:scrollY})");report.AppendLine("SCROLL "+label+" down="+state.y);bool down=state.y>10;yield return Wheel(Point(350*dpr,180*dpr),1);yield return Query("({y:scrollY})");report.AppendLine("SCROLL "+label+" up="+state.y);bool up=state.y==0;
  yield return Wheel(Point(120*dpr,100*dpr),-1);yield return Query("({y:document.getElementById('panel').scrollTop,x:scrollY})");report.AppendLine("SCROLL "+label+" inner="+state.y+" outer="+state.x);bool inner=state.y>10&&state.x==0;
  Check(down&&up&&inner,label+" normalized scroll down/up/nested");
  float innerBefore=state.y;
  yield return Wheel(Point(-30*dpr,100*dpr),-1);yield return Query("({y:document.getElementById('panel').scrollTop,x:scrollY})");Check(state.y==innerBefore&&state.x==0,label+" outside cursor ignored");
  var cover=new GameObject("ScrollOcclusionTest",typeof(RectTransform),typeof(Image));cover.transform.SetParent(host.browser.transform,false);var cr=cover.GetComponent<RectTransform>();cr.anchorMin=Vector2.zero;cr.anchorMax=Vector2.one;cr.offsetMin=cr.offsetMax=Vector2.zero;yield return null;
  yield return Wheel(Point(120*dpr,100*dpr),-1);yield return Query("({y:document.getElementById('panel').scrollTop})");Check(state.y==innerBefore,label+" overlaid UI blocks browser wheel");Destroy(cover);yield return null;
  var oldBehavior=InputSystem.settings.scrollDeltaBehavior;InputSystem.settings.scrollDeltaBehavior=InputSettings.ScrollDeltaBehavior.KeepPlatformSpecificInputRange;
  yield return Wheel(Point(120*dpr,100*dpr),-120);yield return Query("({y:document.getElementById('panel').scrollTop})");Check(state.y>innerBefore+10,label+" native Windows delta supported");InputSystem.settings.scrollDeltaBehavior=oldBehavior;
  yield return Tap(Key.M);Check(GridShiftOperationsUI.Instance.Current==null,label+" wheel/browser focus never opens minimap");
 }
