  yield return new WaitForSecondsRealtime(55);yield return Sample("city-stress");int count=0;foreach(var pedestrians in Object.FindObjectsByType<PedestrianManager>(FindObjectsSortMode.None))count+=pedestrians.Agents.Count;report.AppendLine("STRESS pedestrians="+count+" cars="+TrafficCar.Active.Count);Check(TrafficCar.Active.Distinct().Count()==TrafficCar.Active.Count,"no duplicate traffic registrations");Check(count>=20&&TrafficCar.Active.Count>=20,"populated city stress");Check(manager.fleet.All(v=>v!=null&&v.driver!=null&&v.driver.isActiveAndEnabled),"company fleet remains simulated");
 } IEnumerator OverlayShot(string name){yield return new WaitForSecondsRealtime(.4f);Directory.CreateDirectory("performance-images");var camera=new GameObject("CaptureOverlay7").AddComponent<Camera>();camera.CopyFrom(view);camera.enabled=false;camera.transform.SetPositionAndRotation(view.transform.position,view.transform.rotation);var canvases=Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=.2f;}var target=new RenderTexture(1920,1080,24);camera.targetTexture=target;Canvas.ForceUpdateCanvases();camera.Render();var previous=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes("performance-images/"+name+".png",image.EncodeToPNG());RenderTexture.active=previous;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceOverlay;c.worldCamera=null;}target.Release();Destroy(target);Destroy(image);Destroy(camera.gameObject);}
